<?php
if(!defined('PANIC_ECO_ADMIN') || PANIC_ECO_ADMIN!==true) { http_response_code(403); exit; }
$store=$ecoRepository->purchaseTotals('TIENDA');$storePrev=$ecoRepository->purchaseTotals('TIENDA',true);$buyers=$ecoRepository->storeBuyers();$vip=$ecoRepository->purchaseTotals('VIP');$vipPrev=$ecoRepository->purchaseTotals('VIP',true);$series=$ecoRepository->purchaseSeries();$products=$ecoRepository->storeProducts();$free=$ecoRepository->freeVip();$active=$ecoRepository->activeVip();
panicEcoSentence('Se gastaron '.panicEcoNumber($store['Eryns']).' Eryns en la tienda ('.panicEcoNumber($store['Compras']).' compras de '.panicEcoNumber($buyers['Compradores']).' jugadores) y '.panicEcoNumber($vip['Eryns']).' en VIP ('.panicEcoNumber($vip['Compras']).' compras).','Son gastos de estas fechas. Los VIP activos de abajo muestran el estado de hoy, no el historial del rango.');
if((float)$store['Compras']==0 && (float)$vip['Compras']==0)panicEcoEmpty($ecoFilters['tests']);
$now=new DateTimeImmutable($ecoFilters['now'],new DateTimeZone('America/Argentina/Buenos_Aires'));$limit=$now->modify('+7 days');$expiring=0;
foreach($active as $row){$raw=$row['VipVence'];try{$date=new DateTimeImmutable($raw instanceof DateTimeInterface?$raw->format('Y-m-d H:i:s'):(string)$raw,new DateTimeZone('America/Argentina/Buenos_Aires'));if($date>$now && $date<=$limit)$expiring++;}catch(Throwable $ignored){}}
echo '<div class="eco-metrics eco-metrics--three">';
panicEcoMetric('Gastado en la tienda',$store['Eryns'],'Eryns que gastaron los jugadores en compras de la tienda.',['icon'=>'cart','flow'=>'out','comparison'=>panicEcoComparison($store['Eryns'],$storePrev['Eryns'],panicEcoPeriodWords($ecoFilters))]);
panicEcoMetric('Gastado en VIP',$vip['Eryns'],'Eryns que se descontaron por compras de VIP. Los VIP dados sin cobrar se muestran aparte.',['icon'=>'crown','flow'=>'out','comparison'=>panicEcoComparison($vip['Eryns'],$vipPrev['Eryns'],panicEcoPeriodWords($ecoFilters))]);
panicEcoMetric('VIP activos hoy',count($active),'Jugadores que ahora tienen un VIP sin vencer. Respeta el interruptor de mis pruebas.',['icon'=>'crown','lead'=>'Membresías que siguen vigentes.','comparison'=>panicEcoNumber($expiring).($expiring===1?' vence':' vencen').' en los próximos 7 días.']);echo '</div>';
foreach($products as &$row)$row['Producto']=$row['Producto']?:($row['Indice']!==null?'Artículo '.$row['Indice']:'Artículo sin nombre');unset($row);
echo '<section class="eco-panel"><div class="eco-section-heading"><span class="eco-section-icon">'.panicEcoIcon('cart').'</span><div><h3>Lo más vendido</h3><p>Las 5 compras más elegidas en estas fechas.</p></div></div>';
if(!$products)echo '<p class="eco-note">Todavía no hubo compras para armar esta lista.</p>';else{$max=max(1,panicEcoSum([reset($products)],'Compras'));echo '<ol class="eco-product-list">';foreach(array_slice($products,0,5) as $row){$pct=max(0,min(100,(float)$row['Compras']/$max*100));echo '<li><div><strong>'.panicEcoEscape($row['Producto']).'</strong><span>'.panicEcoNumber($row['Compras']).' compras '.panicEcoHelp('Cantidad de operaciones que incluyeron este artículo; no es una cuenta de unidades.').'</span></div><div class="eco-bar"><span style="width:'.number_format($pct,3,'.','').'%"></span></div></li>';}echo '</ol>';}echo '</section>';
if($free){echo '<div class="eco-alert eco-alert--watch"><span class="eco-alert-icon">'.panicEcoIcon('alert').'</span><div><strong>VIP dado sin cobrar</strong><p>'.(count($free)>=500?'Se muestran al menos 500':('Se detectaron '.panicEcoNumber(count($free)))).' asignaciones en estas fechas. Apareció un VIP sin que se descontaran Eryns: puede ser una asignación manual o una prueba.</p></div></div>';}
panicEcoDetailStart('Compras, artículos, VIP activos y asignaciones sin cobro');
panicEcoTable('Compras en estas fechas',['Periodo'=>'Cuándo','Fuente'=>'Dónde compraron','Compras'=>'Compras','Eryns'=>'Eryns gastados'],$series,['numbers'=>['Compras','Eryns']]);
panicEcoTable('Artículos que se compraron',['Producto'=>'Artículo','Indice'=>'Número de artículo','Compras'=>'Compras','Eryns'=>'Gastado en la tienda · Eryns'],$products,['numbers'=>['Compras','Eryns']]);
if($free)panicEcoTable('VIP dado sin cobrar · últimas 500 asignaciones',['FechaAR'=>'Cuándo','Cuenta'=>'Jugador','Personaje'=>'Personaje','Evento'=>'Qué pasó','Detalle'=>'Más información'],$free,['dates'=>['FechaAR']]);
panicEcoTable('Quiénes tienen VIP hoy',['Cuenta'=>'Jugador','NivelVip'=>'Nivel VIP','VipVence'=>'Cuándo vence','Eryns'=>'Eryns guardados','Prueba'=>'Tipo de cuenta'],$active,['numbers'=>['NivelVip','Eryns'],'dates'=>['VipVence']]);panicEcoDetailEnd();
